"""Deterministic multistart constructor for 26 nonoverlapping circles."""
import numpy as np
from scipy.optimize import linprog, minimize


def construct_packing():
    n = 26
    pairs = np.array([(i, j) for i in range(n) for j in range(i + 1, n)],
                     dtype=int)
    A = np.zeros((len(pairs), n))
    for k, (i, j) in enumerate(pairs):
        A[k, i] = A[k, j] = 1.0

    def margins(p, r=None):
        e = np.column_stack((p[:, 0], p[:, 1], 1-p[:, 0], 1-p[:, 1]))
        if r is not None:
            e = e - r[:, None]
        d = p[pairs[:, 0]] - p[pairs[:, 1]]
        q = np.sqrt(np.sum(d*d, axis=1))
        if r is not None:
            q -= r[pairs[:, 0]] + r[pairs[:, 1]]
        return np.r_[e.ravel(), q]

    def lp_radii(p):
        d = p[pairs[:, 0]] - p[pairs[:, 1]]
        q = np.sqrt(np.sum(d*d, axis=1))
        b = np.min(np.column_stack((p[:, 0], p[:, 1],
                                    1-p[:, 0], 1-p[:, 1])), axis=1)
        return linprog(-np.ones(n), A_ub=A, b_ub=q,
                       bounds=[(1e-7, float(x)) for x in b],
                       method="highs")

    def make_seed(a, phase):
        p = []
        for k, m in enumerate(a):
            # Row-dependent spacing gives the sparse row extra radius capacity.
            y = (k + .5) / len(a)
            if k == 0 or k == len(a)-1:
                y = .075 if k == 0 else .925
            for j in range(m):
                x = (j + .5) / m
                off = phase * (0.027 if k % 2 else -0.021)
                x += off
                p.append((x, y))
        p = np.asarray(p, float)
        # Small inward correction makes all seeds safely interior.
        return np.clip(p, .035, .965)

    def cfun(x, r):
        return margins(x.reshape(n, 2), r)

    def polish(p, r):
        z0 = np.r_[p.ravel(), r]

        def obj(z):
            return -np.sum(z[2*n:])

        def con(z):
            return cfun(z[:2*n], z[2*n:])

        # Bounds are deliberately broad; con() supplies the actual geometry.
        z = minimize(obj, z0, method="SLSQP",
                     bounds=[(0., 1.)] * (2*n) + [(1e-7, .25)] * n,
                     constraints={"type": "ineq", "fun": con},
                     options={"maxiter": 320, "ftol": 4e-9,
                              "disp": False})
        q = z.x if (z.success or np.min(con(z.x)) >= -3e-7) else z0
        if np.min(con(q)) < -3e-7:
            return None
        # Recheck independently and leave a useful numerical safety margin.
        pp = q[:2*n].reshape(n, 2)
        rr = q[2*n:].copy()
        sl = margins(pp, rr)
        if np.min(sl) < 2e-7:
            rr -= max(0., 2.5e-7 - np.min(sl))
        if np.min(margins(pp, rr)) < 1e-7:
            return None
        return pp, rr * (1.0 - 2e-8)

    best = None
    # Mesoscopic alternatives plus the incumbent-like baseline.
    layouts = ((6, 6, 5, 5, 4), (6, 5, 6, 5, 4),
               (6, 5, 5, 6, 4), (5, 6, 5, 4, 6),
               (6, 5, 5, 5, 5))
    for s, layout in enumerate(layouts):
        p = make_seed(layout, -1 if s % 2 else 1)
        # Slightly different vertical compression avoids a rigid row lattice.
        p[:, 1] = .5 + (p[:, 1] - .5) * (1.0 + .012 * (s - 2))
        p = np.clip(p, .025, .975)
        lr = lp_radii(p)
        if not lr.success:
            continue
        ans = polish(p, lr.x)
        if ans is not None:
            pp, rr = ans
            if best is None or rr.sum() > best[1].sum():
                best = (pp, rr)

    if best is None:
        # Guaranteed conservative fallback.
        p = np.array([[.1 + .2*(i % 5), .1 + .2*(i // 5)]
                      for i in range(25)] + [[.5, .9]])
        r = np.full(n, .045)
    else:
        p, r = best
    return p, r, float(np.sum(r))


def compute_max_radii(centers):
    n = len(centers)
    r = np.min(np.column_stack((centers[:, 0], centers[:, 1],
                                1-centers[:, 0], 1-centers[:, 1])), axis=1)
    for i in range(n):
        for j in range(i):
            r[i] = min(r[i], max(0., np.linalg.norm(centers[i]-centers[j])-r[j]))
    return np.maximum(r, 0.) * (1-1e-9)


def run_packing():
    return construct_packing()


def visualize(centers, radii):
    import matplotlib.pyplot as plt
    from matplotlib.patches import Circle
    fig, ax = plt.subplots(figsize=(8, 8))
    ax.set_xlim(0, 1); ax.set_ylim(0, 1); ax.set_aspect("equal")
    for c, r in zip(centers, radii):
        ax.add_patch(Circle(c, r, alpha=.5))
    plt.show()


if __name__ == "__main__":
    c, r, s = run_packing()
    print("Sum of radii:", s)

